// UkInternationalDTO UK-specific international shipment fields. Required when destination country is GB (United Kingdom).
type UkInternationalDTO struct {
	// Amount Number of items / quantity (QITEMS). Must be greater than 0.
	Amount *int `json:"amount"`

	// ContentDescription Description of shipment contents (CCONTENT). Searchable from UK Trade Tariff API.
	ContentDescription *string `json:"contentDescription"`

	// CountryOfOrigin Country of origin ISO alpha-2 code (CORIGIN).
	CountryOfOrigin *string `json:"countryOfOrigin"`

	// Currency Currency ISO 4217 code (CURRENCY). E.g. EUR, USD, GBP.
	Currency *string `json:"currency"`

	// GrossWeight Gross weight in kg (CGROSSWEIGHT). Must be greater than 0 and >= netWeight.
	GrossWeight *float32 `json:"grossWeight"`

	// HsCode HS Tariff code (RCTARIF / SCTARIF). 6–8 numeric digits only.
	HsCode *string `json:"hsCode"`

	// InvoiceAmount Invoice line amount (CAMOUNTLINE). Digits only.
	InvoiceAmount *string `json:"invoiceAmount"`

	// InvoiceNumber Commercial invoice number (CINVOICE). Digits only.
	InvoiceNumber *string `json:"invoiceNumber"`

	// NetWeight Net weight in kg (CNETWEIGHT). Must be greater than 0.
	NetWeight *float32 `json:"netWeight"`

	// PaymentTerm Payment term (PAYMENTTERM). Incoterms code.
	PaymentTerm *UkInternationalDTOPaymentTerm `json:"paymentTerm"`

	// ReasonForExport Reason for export (REASONFOREXPORT). s01=sale, s02=return/replacement, s03=gift.
	ReasonForExport *UkInternationalDTOReasonForExport `json:"reasonForExport"`

	// ReceiverEori Receiver EORI number (REORI). Mandatory for business receivers. Must start with ISO country code + 12-digit number.
	ReceiverEori *string `json:"receiverEori"`

	// ReceiverType Indicates whether the receiver is a business or private individual. Determines if receiverEori is mandatory.
	ReceiverType *UkInternationalDTOReceiverType `json:"receiverType"`

	// ReturnAddress Optional return address free text. Expected: House No, Street, City, Postal Code.
	ReturnAddress *string `json:"returnAddress"`

	// SenderEori Sender EORI number (SEORI). Must start with LT, LV, or EE, max 17 chars.
	SenderEori *string `json:"senderEori"`

	// SenderVat Sender VAT number (SVATNO). Optional. Format depends on sender country (LT/LV/EE).
	SenderVat *string `json:"senderVat"`
}

